def upgrade() -> None:
    """Upgrade schema."""
    # ### commands auto generated by Alembic - please adjust! ###
    op.add_column('messages', sa.Column('status', sa.String(length=20), server_default='sent', nullable=False))
    op.add_column('messages', sa.Column('sending_since', sa.DateTime(timezone=True), nullable=True))
    # ### end Alembic commands ###
    # Added by hand: autogenerate doesn't detect CHECK constraints on existing
    # tables. Every existing message becomes "sent" with no sending_since, so
    # all three checks pass.
    op.create_check_constraint(op.f('ck_messages_status_valid'), 'messages', "status IN ('sent', 'sending', 'failed')")
    op.create_check_constraint(
        op.f('ck_messages_unsent_only_for_questions'), 'messages', "status = 'sent' OR role = 'user'",
    )
    op.create_check_constraint(
        op.f('ck_messages_sending_since_while_sending'), 'messages',
        "(status = 'sending') = (sending_since IS NOT NULL)",
    )
    # Added by hand: questions whose reply failed before this column existed.
    # A failed reply was never saved, so they are the customer messages that
    # are still the last message of their conversation. The 5 minutes leave
    # out a question whose reply might be on its way during the upgrade.
    op.execute("""
        UPDATE messages m SET status = 'failed'
        WHERE m.role = 'user'
          AND m.created_at < now() - interval '5 minutes'
          AND NOT EXISTS (
              SELECT 1 FROM messages later
              WHERE later.conversation_id = m.conversation_id
                AND (later.created_at, later.id) > (m.created_at, m.id)
          )
    """)


